import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .b8 smem_raw[];
// CTA-tiled depthwise conv2d with kernel (k,1).
// Each CTA computes a (64 x tile_w) output tile for one (n,c) plane.
// The required (RH x CW) input patch (including halo) is cooperatively
// staged in shared memory once and reused by all output rows, removing
// the k-fold redundant global-memory reads of the direct kernel.
// Optimization: asynchronous 128-bit staged loads (cp.async).
// Each thread computes 8 consecutive output columns (register blocking):
// tile chunks are staged with cp.async.cg 16B copies (no register
// round-trip, all copies in flight, single wait before bar.sync);
// zero/edge chunks and all fallbacks keep ld.global/st.shared.v4 paths.
// The k-loop uses ld.shared.v4 (stride==1), and outputs are written
// with st.global.v4 (bounds/alignment guarded, scalar fallbacks kept).
// Requires tile_w == 64 (enforced by the launch glue, which falls back
// to depthwise_conv2d_kx1_generic otherwise).
.visible .entry depthwise_conv2d_kx1(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 channels,
    .param .s32 height,
    .param .s32 width,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 ksize,
    .param .s32 stride,
    .param .s32 pad,
    .param .s32 dil,
    .param .s32 has_bias,
    .param .s32 tile_w,
    .param .s32 ow_tiles,
    .param .s32 oh_tiles
)
{
    .reg .pred %p<24>;
    .reg .b32 %r<96>;
    .reg .b64 %rd<32>;
    .reg .f32 %f<32>;
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r34, %ntid.x;
    ld.param.s32 %r3, [ow_tiles];
    rem.s32 %r4, %r2, %r3;                  // owt
    div.s32 %r5, %r2, %r3;
    ld.param.s32 %r6, [oh_tiles];
    rem.s32 %r7, %r5, %r6;                  // oht
    div.s32 %r8, %r5, %r6;                  // nc
    ld.param.s32 %r9, [stride];
    ld.param.s32 %r10, [pad];
    ld.param.s32 %r11, [ksize];
    ld.param.s32 %r12, [dil];
    ld.param.s32 %r13, [width];
    ld.param.s32 %r14, [height];
    ld.param.s32 %r15, [out_w];
    ld.param.s32 %r16, [out_h];
    ld.param.s32 %r17, [channels];
    ld.param.s32 %r18, [tile_w];
    mul.lo.s32 %r19, %r4, %r18;             // ow0 = owt * tw
    shl.b32 %r20, %r7, 6;                   // oh0 = oht * 64
    mul.lo.s32 %r21, %r19, %r9;
    sub.s32 %r21, %r21, %r10;               // iw0
    mul.lo.s32 %r22, %r20, %r9;
    sub.s32 %r22, %r22, %r10;               // ih0
    mul.lo.s32 %r23, %r9, 63;               // 63*s
    add.s32 %r55, %r11, -1;
    mul.lo.s32 %r55, %r55, %r12;            // (k-1)*d
    add.s32 %r23, %r23, %r55;
    add.s32 %r23, %r23, 1;                  // RH
    add.s32 %r56, %r18, -1;
    mul.lo.s32 %r24, %r56, %r9;
    add.s32 %r24, %r24, 1;                  // CW = (tw-1)*s + 1
    mul.lo.s32 %r25, %r23, %r24;            // RH*CW (staging trip count)
    add.s32 %r67, %r24, 4;                  // RS = CW + 4 (padded row stride)
    rem.s32 %r26, %r8, %r17;                // c
    mov.u32 %r27, smem_raw;                 // shared tile base
    mul.lo.s32 %r28, %r23, %r67;            // RH*RS
    shl.b32 %r28, %r28, 2;
    add.u32 %r29, %r27, %r28;               // shared weight base
    // cooperative load of k weights for channel c
    mov.s32 %r33, %r1;
W_LOOP:
    setp.ge.s32 %p1, %r33, %r11;
    @%p1 bra W_DONE;
    mad.lo.s32 %r30, %r26, %r11, %r33;      // c*k + idx
    cvt.u64.s32 %rd1, %r30;
    shl.b64 %rd2, %rd1, 2;
    ld.param.u64 %rd3, [wt_ptr];
    add.s64 %rd4, %rd3, %rd2;
    ld.global.f32 %f1, [%rd4];
    shl.b32 %r31, %r33, 2;
    add.u32 %r32, %r29, %r31;
    st.shared.f32 [%r32], %f1;
    add.s32 %r33, %r33, %r34;
    bra W_LOOP;
W_DONE:
    // vector staging guard: CW%4==0 && width%4==0 && iw0%4==0
    and.b32 %r61, %r24, 3;
    setp.eq.s32 %p14, %r61, 0;
    and.b32 %r62, %r13, 3;
    setp.eq.s32 %p15, %r62, 0;
    and.pred %p14, %p14, %p15;
    and.b32 %r63, %r21, 3;
    setp.eq.s32 %p16, %r63, 0;
    and.pred %p14, %p14, %p16;
    @!%p14 bra TILE_SCALAR;
    shr.u32 %r57, %r24, 2;                  // 4-float chunks per row
    mul.lo.s32 %r58, %r23, %r57;            // total chunks
    mov.s32 %r33, %r1;
V_LOOP:
    setp.ge.s32 %p2, %r33, %r58;
    @%p2 bra TILE_SYNC;
    div.s32 %r35, %r33, %r57;               // r
    rem.s32 %r36, %r33, %r57;               // cq
    shl.b32 %r36, %r36, 2;                  // col = cq*4
    add.s32 %r37, %r22, %r35;               // ih
    add.s32 %r38, %r21, %r36;               // iw
    mul.lo.s32 %r39, %r35, %r67;             // r*RS
    add.s32 %r39, %r39, %r36;                // + col
    shl.b32 %r39, %r39, 2;                   // padded smem byte offset
    add.u32 %r40, %r27, %r39;
    setp.lt.s32 %p3, %r37, 0;
    setp.ge.s32 %p4, %r37, %r14;
    or.pred %p5, %p3, %p4;
    @%p5 bra V_ZERO;
    add.s32 %r59, %r38, 3;
    setp.lt.s32 %p6, %r38, 0;
    setp.ge.s32 %p7, %r59, %r13;
    or.pred %p8, %p6, %p7;
    @%p8 bra V_EDGE;
    cvt.u64.s32 %rd5, %r8;
    cvt.u64.s32 %rd6, %r14;
    mul.lo.u64 %rd7, %rd5, %rd6;
    cvt.u64.s32 %rd8, %r37;
    add.s64 %rd7, %rd7, %rd8;
    cvt.u64.s32 %rd9, %r13;
    mul.lo.u64 %rd7, %rd7, %rd9;
    cvt.u64.s32 %rd10, %r38;
    add.s64 %rd7, %rd7, %rd10;
    shl.b64 %rd7, %rd7, 2;
    ld.param.u64 %rd11, [in_ptr];
    add.s64 %rd12, %rd11, %rd7;
    cp.async.cg.shared.global [%r40], [%rd12], 16;
    bra V_NEXT;
V_ZERO:
    mov.f32 %f13, 0f00000000;
    st.shared.v4.f32 [%r40], {%f13,%f13,%f13,%f13};
    bra V_NEXT;
V_EDGE:
    cvt.u64.s32 %rd5, %r8;
    cvt.u64.s32 %rd6, %r14;
    mul.lo.u64 %rd7, %rd5, %rd6;
    cvt.u64.s32 %rd8, %r37;
    add.s64 %rd7, %rd7, %rd8;
    cvt.u64.s32 %rd9, %r13;
    mul.lo.u64 %rd7, %rd7, %rd9;
    cvt.u64.s32 %rd10, %r38;
    add.s64 %rd7, %rd7, %rd10;
    shl.b64 %rd7, %rd7, 2;
    ld.param.u64 %rd11, [in_ptr];
    add.s64 %rd12, %rd11, %rd7;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f14, 0f00000000;
    mov.f32 %f15, 0f00000000;
    mov.f32 %f16, 0f00000000;
    setp.lt.s32 %p9, %r38, 0;
    setp.ge.s32 %p10, %r38, %r13;
    or.pred %p9, %p9, %p10;
    @!%p9 ld.global.f32 %f13, [%rd12];
    add.s32 %r60, %r38, 1;
    setp.lt.s32 %p9, %r60, 0;
    setp.ge.s32 %p10, %r60, %r13;
    or.pred %p9, %p9, %p10;
    @!%p9 ld.global.f32 %f14, [%rd12+4];
    add.s32 %r60, %r38, 2;
    setp.lt.s32 %p9, %r60, 0;
    setp.ge.s32 %p10, %r60, %r13;
    or.pred %p9, %p9, %p10;
    @!%p9 ld.global.f32 %f15, [%rd12+8];
    add.s32 %r60, %r38, 3;
    setp.lt.s32 %p9, %r60, 0;
    setp.ge.s32 %p10, %r60, %r13;
    or.pred %p9, %p9, %p10;
    @!%p9 ld.global.f32 %f16, [%rd12+12];
    st.shared.v4.f32 [%r40], {%f13,%f14,%f15,%f16};
V_NEXT:
    add.s32 %r33, %r33, %r34;
    bra V_LOOP;
TILE_SCALAR:
    mov.s32 %r33, %r1;
TS_LOOP:
    setp.ge.s32 %p2, %r33, %r25;
    @%p2 bra TILE_SYNC;
    div.s32 %r35, %r33, %r24;               // r
    rem.s32 %r36, %r33, %r24;               // col
    add.s32 %r37, %r22, %r35;               // ih
    add.s32 %r38, %r21, %r36;               // iw
    mov.f32 %f2, 0f00000000;
    setp.lt.s32 %p3, %r37, 0;
    setp.ge.s32 %p4, %r37, %r14;
    or.pred %p5, %p3, %p4;
    setp.lt.s32 %p6, %r38, 0;
    or.pred %p5, %p5, %p6;
    setp.ge.s32 %p7, %r38, %r13;
    or.pred %p5, %p5, %p7;
    @%p5 bra TS_STORE;
    cvt.u64.s32 %rd5, %r8;
    cvt.u64.s32 %rd6, %r14;
    mul.lo.u64 %rd7, %rd5, %rd6;
    cvt.u64.s32 %rd8, %r37;
    add.s64 %rd7, %rd7, %rd8;
    cvt.u64.s32 %rd9, %r13;
    mul.lo.u64 %rd7, %rd7, %rd9;
    cvt.u64.s32 %rd10, %r38;
    add.s64 %rd7, %rd7, %rd10;
    shl.b64 %rd7, %rd7, 2;
    ld.param.u64 %rd11, [in_ptr];
    add.s64 %rd12, %rd11, %rd7;
    ld.global.f32 %f2, [%rd12];
TS_STORE:
    mul.lo.s32 %r39, %r35, %r67;             // r*RS + col
    add.s32 %r39, %r39, %r36;
    shl.b32 %r39, %r39, 2;
    add.u32 %r40, %r27, %r39;
    st.shared.f32 [%r40], %f2;
    add.s32 %r33, %r33, %r34;
    bra TS_LOOP;
TILE_SYNC:
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    // register blocking: 8 column-groups (8 outputs each) x 64 row lanes
    and.b32 %r41, %r1, 7;                   // tx8
    shr.u32 %r42, %r1, 3;                   // ty = row lane (0..63)
    shl.b32 %r43, %r41, 3;                  // col8 = tx8*8
    add.s32 %r44, %r19, %r43;               // ow_base
    mul.lo.s32 %r46, %r43, %r9;             // iw_local0 = col8*s
    shl.b32 %r54, %r9, 2;                   // lane byte stride = s*4
    ld.param.s32 %r52, [has_bias];
    setp.eq.s32 %p12, %r52, 0;
    mov.f32 %f12, 0f00000000;
    @%p12 bra BIAS_DONE;
    cvt.u64.s32 %rd13, %r26;
    shl.b64 %rd14, %rd13, 2;
    ld.param.u64 %rd15, [bias_ptr];
    add.s64 %rd16, %rd15, %rd14;
    ld.global.f32 %f12, [%rd16];
BIAS_DONE:
    add.s32 %r47, %r20, %r42;               // oh = oh0 + ty
    setp.ge.s32 %p10, %r47, %r16;
    @%p10 bra DONE;
    mul.lo.s32 %r48, %r42, %r9;             // row_base = ty*s
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;
    mov.f32 %f5, 0f00000000;
    mov.f32 %f6, 0f00000000;
    mov.f32 %f17, 0f00000000;
    mov.f32 %f18, 0f00000000;
    mov.f32 %f19, 0f00000000;
    mov.f32 %f20, 0f00000000;
    mov.s32 %r49, 0;                        // kh
K_LOOP:
    setp.ge.s32 %p11, %r49, %r11;
    @%p11 bra K_DONE;
    mad.lo.s32 %r50, %r49, %r12, %r48;      // row = row_base + kh*d
    mul.lo.s32 %r51, %r50, %r67;            // row*RS (padded)
    add.s32 %r51, %r51, %r46;               // + iw_local0
    shl.b32 %r51, %r51, 2;
    add.u32 %r51, %r51, %r27;
    shl.b32 %r64, %r49, 2;
    add.u32 %r64, %r64, %r29;
    ld.shared.f32 %f11, [%r64];             // weight[kh]
    setp.ne.s32 %p13, %r9, 1;
    @%p13 bra K_SCALAR;
    ld.shared.v4.f32 {%f7,%f8,%f9,%f10}, [%r51];
    ld.shared.v4.f32 {%f21,%f22,%f23,%f24}, [%r51+16];
    bra K_FMA;
K_SCALAR:
    ld.shared.f32 %f7, [%r51];
    add.u32 %r65, %r51, %r54;
    ld.shared.f32 %f8, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f9, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f10, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f21, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f22, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f23, [%r65];
    add.u32 %r65, %r65, %r54;
    ld.shared.f32 %f24, [%r65];
K_FMA:
    fma.rn.f32 %f3, %f7, %f11, %f3;
    fma.rn.f32 %f4, %f8, %f11, %f4;
    fma.rn.f32 %f5, %f9, %f11, %f5;
    fma.rn.f32 %f6, %f10, %f11, %f6;
    fma.rn.f32 %f17, %f21, %f11, %f17;
    fma.rn.f32 %f18, %f22, %f11, %f18;
    fma.rn.f32 %f19, %f23, %f11, %f19;
    fma.rn.f32 %f20, %f24, %f11, %f20;
    add.s32 %r49, %r49, 1;
    bra K_LOOP;
K_DONE:
    add.f32 %f3, %f3, %f12;
    add.f32 %f4, %f4, %f12;
    add.f32 %f5, %f5, %f12;
    add.f32 %f6, %f6, %f12;
    add.f32 %f17, %f17, %f12;
    add.f32 %f18, %f18, %f12;
    add.f32 %f19, %f19, %f12;
    add.f32 %f20, %f20, %f12;
    cvt.u64.s32 %rd17, %r8;
    cvt.u64.s32 %rd18, %r16;
    mul.lo.u64 %rd19, %rd17, %rd18;
    cvt.u64.s32 %rd20, %r47;
    add.s64 %rd19, %rd19, %rd20;
    cvt.u64.s32 %rd21, %r15;
    mul.lo.u64 %rd19, %rd19, %rd21;
    cvt.u64.s32 %rd22, %r44;
    add.s64 %rd19, %rd19, %rd22;
    shl.b64 %rd19, %rd19, 2;
    ld.param.u64 %rd23, [out_ptr];
    add.s64 %rd24, %rd23, %rd19;
    add.s32 %r66, %r44, 7;
    setp.lt.s32 %p17, %r66, %r15;           // ow_base+7 < out_w
    and.b64 %rd25, %rd24, 15;
    setp.eq.u64 %p18, %rd25, 0;             // 16B aligned
    and.pred %p19, %p17, %p18;
    @%p19 bra STORE_VEC;
    setp.lt.s32 %p20, %r44, %r15;
    @%p20 st.global.f32 [%rd24], %f3;
    add.s32 %r68, %r44, 1;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+4], %f4;
    add.s32 %r68, %r44, 2;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+8], %f5;
    add.s32 %r68, %r44, 3;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+12], %f6;
    add.s32 %r68, %r44, 4;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+16], %f17;
    add.s32 %r68, %r44, 5;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+20], %f18;
    add.s32 %r68, %r44, 6;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+24], %f19;
    add.s32 %r68, %r44, 7;
    setp.lt.s32 %p21, %r68, %r15;
    @%p21 st.global.f32 [%rd24+28], %f20;
    bra DONE;
STORE_VEC:
    st.global.v4.f32 [%rd24], {%f3,%f4,%f5,%f6};
    st.global.v4.f32 [%rd24+16], {%f17,%f18,%f19,%f20};
DONE:
    ret;
}
// Generic fallback (original scalar kernel) for tile_w != 64.
.visible .entry depthwise_conv2d_kx1_generic(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .s32 channels,
    .param .s32 height,
    .param .s32 width,
    .param .s32 out_h,
    .param .s32 out_w,
    .param .s32 ksize,
    .param .s32 stride,
    .param .s32 pad,
    .param .s32 dil,
    .param .s32 has_bias,
    .param .s32 tile_w,
    .param .s32 ow_tiles,
    .param .s32 oh_tiles
)
{
    .reg .pred %p<16>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<32>;
    .reg .f32 %f<16>;
    mov.u32 %r1, %tid.x;
    mov.u32 %r2, %ctaid.x;
    mov.u32 %r34, %ntid.x;
    ld.param.s32 %r3, [ow_tiles];
    rem.s32 %r4, %r2, %r3;                  // owt
    div.s32 %r5, %r2, %r3;
    ld.param.s32 %r6, [oh_tiles];
    rem.s32 %r7, %r5, %r6;                  // oht
    div.s32 %r8, %r5, %r6;                  // nc
    ld.param.s32 %r9, [stride];
    ld.param.s32 %r10, [pad];
    ld.param.s32 %r11, [ksize];
    ld.param.s32 %r12, [dil];
    ld.param.s32 %r13, [width];
    ld.param.s32 %r14, [height];
    ld.param.s32 %r15, [out_w];
    ld.param.s32 %r16, [out_h];
    ld.param.s32 %r17, [channels];
    ld.param.s32 %r18, [tile_w];
    mul.lo.s32 %r19, %r4, %r18;             // ow0 = owt * tw
    shl.b32 %r20, %r7, 6;                   // oh0 = oht * 64
    mul.lo.s32 %r21, %r19, %r9;
    sub.s32 %r21, %r21, %r10;               // iw0
    mul.lo.s32 %r22, %r20, %r9;
    sub.s32 %r22, %r22, %r10;               // ih0
    mul.lo.s32 %r23, %r9, 63;               // 63*s
    add.s32 %r55, %r11, -1;
    mul.lo.s32 %r55, %r55, %r12;            // (k-1)*d
    add.s32 %r23, %r23, %r55;
    add.s32 %r23, %r23, 1;                  // RH
    add.s32 %r56, %r18, -1;
    mul.lo.s32 %r24, %r56, %r9;
    add.s32 %r24, %r24, 1;                  // CW = (tw-1)*s + 1
    mul.lo.s32 %r25, %r23, %r24;            // RH*CW
    rem.s32 %r26, %r8, %r17;                // c
    mov.u32 %r27, smem_raw;                 // shared tile base
    shl.b32 %r28, %r25, 2;
    add.u32 %r29, %r27, %r28;               // shared weight base
    // cooperative load of k weights for channel c
    mov.s32 %r33, %r1;
W_LOOP:
    setp.ge.s32 %p1, %r33, %r11;
    @%p1 bra W_DONE;
    mad.lo.s32 %r30, %r26, %r11, %r33;      // c*k + idx
    cvt.u64.s32 %rd1, %r30;
    shl.b64 %rd2, %rd1, 2;
    ld.param.u64 %rd3, [wt_ptr];
    add.s64 %rd4, %rd3, %rd2;
    ld.global.f32 %f1, [%rd4];
    shl.b32 %r31, %r33, 2;
    add.u32 %r32, %r29, %r31;
    st.shared.f32 [%r32], %f1;
    add.s32 %r33, %r33, %r34;
    bra W_LOOP;
W_DONE:
    // cooperative load of the (RH x CW) input patch, zero-filled halo
    mov.s32 %r33, %r1;
