_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("depthwise_conv2d_kx1")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, in_channels, kernel_size=(kernel_size, 1), stride=stride, padding=padding, dilation=dilation, groups=in_channels, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        n, c, h, w = x.shape
        k = int(self.conv2d.kernel_size[0])
        s = int(self.conv2d.stride[0])
        p = int(self.conv2d.padding[0])
        d = int(self.conv2d.dilation[0])

        oh = (h + 2 * p - d * (k - 1) - 1) // s + 1
        ow = (w + 2 * p - 1) // s + 1
        out = torch.empty((n, c, oh, ow), device=x.device, dtype=x.dtype)

        total = n * c * oh * ow
        if total != 0:
            module = _get_ptx_module()
            bias_tensor = self.conv2d.bias if self.conv2d.bias is not None else out
            has_bias = 1 if self.conv2d.bias is not None else 0
            module.launch(
                "depthwise_conv2d_kx1",
                grid=((total + 255) // 256, 1, 1),
                block=(256, 1, 1),
                arguments=[
                    x,
                    self.conv2d.weight,
                    bias_tensor,
                    out,
                    i32(total),
                    i32(c),
                    i32(h),
                    i32(w),
                    i32(oh),
                    i32(ow),
                    i32(k),
                    i32(s),
                    i32(p),
                    i32(d),
                    i32(has_bias),
                ],
                shared_memory=0,
                stream=torch.cuda.current_stream(x.device),
            )
        return out
